   508			if (bytes_to_drop>remain) {
   509				GF_LOG(GF_LOG_WARNING, GF_LOG_MEDIA, ("[ADTSDmx] truncated AC3 frame!\n"));
   510				bytes_to_drop=remain;
   511			}
   512	
   513			if (!bytes_to_drop) {
   514				bytes_to_drop = 1;
   515			}
   516			start += bytes_to_drop;
   517			remain -= bytes_to_drop;
   518			gf_bs_reassign_buffer(ctx->bs, start, remain);
