   520			if (prev_pck_size) {
   521				if (prev_pck_size > bytes_to_drop) prev_pck_size -= bytes_to_drop;
   522				else {
   523					prev_pck_size=0;
   524					if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
