   537			goto restart;
   538		} else {
   539			if (remain && (remain < ctx->ac3_buffer_size)) {
   540				memmove(ctx->ac3_buffer, start, remain);
   541			}
   542			ctx->ac3_buffer_size = remain;
   543			gf_filter_pid_drop_packet(ctx->ipid);
   544		}
   545		return GF_OK;
   546	}
